/**
 * The branch template pool: pure data, no engine logic. Authoring a new
 * template means adding an entry to BRANCH_TEMPLATES — engine.ts never needs
 * to change, which is the property the spec asks for explicitly (and the
 * property Roguelike-Snake's relic pool lacked: every relic there was a
 * bespoke engine branch, so nobody added any and two runs shared 72% of what
 * they carried).
 *
 * Every template's obstacle count is generated by `evenObstacles`, a small
 * layout helper local to this file. It exists only to keep authoring safe —
 * same-lane obstacles come out spaced at least MIN_SAME_LANE_SPACING apart by
 * construction — but the OUTPUT is a plain array baked in at module load, so
 * from the engine's point of view a template is exactly as "just data" as if
 * every offset had been typed by hand.
 */
import {
  LANE_COUNT,
  MIN_LEAD_IN,
  MIN_TRAIL_OUT,
  densityFloor,
  type BranchTemplate,
  type Obstacle,
  type ObstacleKind,
  type RewardKind,
  type SpeedTier,
} from './constants';

function evenObstacles(length: number, count: number, kinds: ObstacleKind[]): Obstacle[] {
  const start = MIN_LEAD_IN;
  const end = length - MIN_TRAIL_OUT;
  const span = Math.max(0, end - start);
  const step = count > 1 ? span / (count - 1) : 0;
  const out: Obstacle[] = [];
  for (let i = 0; i < count; i++) {
    out.push({
      offset: Math.round(start + step * i),
      lane: i % LANE_COUNT,
      kind: kinds[i % kinds.length],
    });
  }
  return out;
}

function template(
  id: string,
  name: string,
  speed: SpeedTier,
  reward: RewardKind,
  length: number,
  count: number,
  kinds: ObstacleKind[],
  unlockDistance: number,
): BranchTemplate {
  const floor = densityFloor(speed, reward);
  if (count < floor) {
    // A template authored below its own axis rules would be exactly the
    // silent-lie failure mode this repo has hit before: text (and here, the
    // pool itself) promising a rule the data does not actually keep. Fail at
    // import time rather than trusting every future author to do the algebra.
    throw new Error(`${id}: density ${count} is below the floor ${floor} for ${speed}/${reward}`);
  }
  return {
    id,
    name,
    speed,
    reward,
    rewardOffset: Math.round(length * 0.55),
    length,
    obstacles: evenObstacles(length, count, kinds),
    unlockDistance,
  };
}

