export function eligibleTemplates(distance: number): BranchTemplate[] {
  return BRANCH_TEMPLATES.filter((t) => t.unlockDistance <= distance);
}

export const TEMPLATE_BY_ID: Record<string, BranchTemplate> = Object.fromEntries(
  BRANCH_TEMPLATES.map((t) => [t.id, t]),
);
